-- Run after schema.sql (safe to re-run). Upserts the themes; does not change which one is active.
delete from themes where name in ('dome','kaaba','haram-night');
on conflict (name) do update set json = excluded.json;
-- if the active theme was one of the removed ones, fall back to default
update themes set active = true where name = 'default' and not exists (select 1 from themes where active);
